#!/usr/bin/env python3
"""Проверка ссылок в документах: каждая ссылка вида [текст](путь) ведёт на существующий файл.

Примеры:
    python3 tools/check_links.py             # все docs/ и specs/
    python3 tools/check_links.py docs/        # только каталог

Код выхода 0 — битых ссылок нет, 1 — есть (печатаются файл, строка и ссылка).
"""
import pathlib
import re
import sys

ССЫЛКА = re.compile(r"\]\(([^)#\s]+)")


def main() -> int:
    корни = [pathlib.Path(п) for п in sys.argv[1:]] or [pathlib.Path("docs"), pathlib.Path("specs")]
    битых = 0
    for корень in корни:
        for файл in sorted(корень.rglob("*.md")):
            for номер, строка in enumerate(файл.read_text(encoding="utf-8").splitlines(), start=1):
                for цель in ССЫЛКА.findall(строка):
                    if "://" in цель:
                        continue
                    if not (файл.parent / цель).exists():
                        print(f"{файл}:{номер}: {цель}")
                        битых += 1
    return 1 if битых else 0


if __name__ == "__main__":
    sys.exit(main())
